assignments.value:
={{ (() => {
  const batch = new Set($('Get Pending Messages').all().map(i => i.json.message_id));
  const who = { in: 'Customer', out: 'You', staff: 'Team member' };
  return $('Get Chat History').all().map(i => i.json)
    .filter(r => r.text && r.direction && !batch.has(r.message_id))
    .reverse()
    .slice(-$('Sales Settings').first().json.history_messages)
    .map(r => (who[r.direction] ?? r.direction) + ': ' + String(r.text).replace(/\s+/g, ' ').slice(0, 600))
    .join('\n');
})() }}

