      f.order.items.map(i => '<tr><td>' + i.quantity + ' ×</td><td>' + esc(i.product) + '</td><td>' + esc(i.sku) + '</td><td>' + i.unit_price + '</td></tr>').join('') +
      '<tr><td colspan="3"><b>Subtotal</b></td><td><b>' + total + '</b></td></tr></table>' +
      '<p><b>Recipient:</b> ' + esc(f.order.recipient_name) + '<br><b>Address:</b> ' + esc(f.order.address) + (f.order.notes ? '<br><b>Notes:</b> ' + esc(f.order.notes) : '') + '</p>' +
      '<p>Confirm shipping cost and payment with the customer, then update the Orders sheet.</p>';
  }
  if (f.handoff) html += '<h3 style="margin:16px 0 8px">The AI handed this chat to you</h3><p><b>Reason:</b> ' + esc(f.handoff_reason) + '</p><p>The AI stays silent for this customer for ' + $('Sales Settings').first().json.human_pause_hours + ' hours.</p>';
  html += '<h4 style="margin:16px 0 4px">Latest messages</h4><pre style="white-space:pre-wrap;background:#f6f6f6;padding:8px">' +
    esc((a.history ? a.history.split('\n').slice(-6).join('\n') + '\n' : '') + 'Customer: ' + a.new_messages + '\nYou: ' + f.reply) + '</pre>';
  html += '<p><a href="' + base + '?phone=' + m.phone + '">Reply from the n8n form</a> · <a href="https://wa.me/' + m.phone + '">Open in WhatsApp</a></p></div>';
  return html;
})() }}

conditions.leftValue:
={{ (() => {
  const cfg = $('Follow-up Settings').first().json;
  const stages = String(cfg.followup_stages).split(',').map(s => s.trim());
  if (!stages.includes($json.stage) || !$json.last_inbound_at) return false;
  const hours = $now.diff(DateTime.fromISO($json.last_inbound_at), 'hours').hours;
  return hours >= cfg.followup_after_hours && hours < 23.5;
})() }}

parameters.jsCode:
// Scores every catalog row against the search words and returns the best 8.
const input = $('When Catalog Is Searched').first().json;
const norm = s => String(s ?? '').toLowerCase().normalize('NFKD').replace(/[^\p{L}\p{N}\s]/gu, ' ');
const words = norm(input.query).split(/\s+/).filter(w => w.length > 1);
const maxPrice = Number(input.max_price) > 0 ? Number(input.max_price) : Infinity;
const category = norm(input.category).trim();
const toNumber = v => {
  if (typeof v === 'number') return v;
  const n = Number(String(v ?? '').replace(/[^\d.,-]/g, '').replace(/[.,](?=\d{3}(\D|$))/g, '').replace(',', '.'));
  return Number.isFinite(n) ? n : null;
};

const rows = $input.all().map(i => i.json).filter(r => r && (r.Name || r.name));
const scored = rows.map(r => {
  const p = {
    sku: String(r.SKU ?? r.sku ?? ''),
    name: String(r.Name ?? r.name ?? ''),
    category: String(r.Category ?? r.category ?? ''),
    price: toNumber(r.Price ?? r.price),
    stock: toNumber(r.Stock ?? r.stock),
    description: String(r.Description ?? r.description ?? '').slice(0, 300),
    link: String(r.Link ?? r.link ?? ''),
  };
  const name = norm(p.name), cat = norm(p.category), desc = norm(p.description);
  let score = 0;
  for (const w of words) {
    if (name.includes(w)) score += 3;
    if (cat.includes(w)) score += 2;
    if (desc.includes(w)) score += 1;
  }
  if (category && cat.includes(category)) score += 2;
  if (p.stock !== null && p.stock <= 0) score -= 1;
  return { p, score };
}).filter(x => (x.p.price === null || x.p.price <= maxPrice) && (words.length === 0 || x.score > 0));

scored.sort((a, b) => b.score - a.score);
const products = scored.slice(0, 8).map(x => x.p);
return [{ json: { found: products.length, total_in_catalog: rows.length, products } }];

